from pathlib import Path
p=Path('www/index.html')
s=p.read_text(encoding='utf-8')
css=r'''<style id="v37-validated-ui">
:root{--k-text-scale:1;--k-menu-scale:.86;--bg:#07121f!important;--surface:#0d1b2a!important;--ink:#f2f7f8!important;--muted:#8ea3ad!important;--line:#1b3543!important;--accent:#31c6ad!important;--accent-ink:#041411!important;--chip:#102b31!important;color-scheme:dark!important}
html,body{background:#07121f!important;color:#f2f7f8!important}body{font-size:calc(14px * var(--k-text-scale))!important;padding-bottom:66px}.sticky{background:rgba(7,18,31,.96)!important;backdrop-filter:blur(18px)}header.top{padding:8px max(14px,env(safe-area-inset-right))!important;gap:9px!important;border-color:#18313f!important}.brand{font:700 22px/1 var(--f-head)!important}.brand svg{width:34px!important;height:34px!important}.round{width:34px!important;height:34px!important;background:#0d1b2a!important;border-color:#244252!important}.searchwrap{max-width:none!important}.search{background:#0b1a28!important;border-color:#244252!important;padding-top:8px!important;padding-bottom:8px!important}.tools{gap:5px!important}.stamp{display:none!important}
.menuwrap{border-color:#18313f!important}.menubar{padding:6px 14px!important;gap:6px!important}.menubar button{background:#0d1b2a!important;border-color:#203c49!important;padding:6px 11px!important;font-size:calc(12px * var(--k-menu-scale) + 2px)!important}.menubar button[aria-current=true]{background:#31c6ad!important;color:#041411!important;border-color:#31c6ad!important}.submenu{background:#091724!important;border-color:#18313f!important}.submenu button{padding:7px 10px!important;font-size:12px!important}
.layout{grid-template-columns:190px minmax(0,1fr)!important;gap:18px!important;max-width:1180px!important;padding:14px 14px 36px!important}nav.sources{top:120px!important;background:#0a1825;border:1px solid #173442;border-radius:16px;padding:10px!important}.navlabel{margin:3px 7px 7px!important}.src{display:flex!important;align-items:center!important;gap:8px!important;min-height:36px!important;border-radius:10px!important;padding:6px 8px!important}.src .klogo{width:24px;height:24px;border-radius:6px;object-fit:contain;background:white;flex:none}
.card,.article,.item{background:#0d1b2a!important;border:1px solid #173442!important;border-radius:15px!important;box-shadow:0 8px 28px #0002!important}.card,.item{padding:12px!important}.grid{gap:12px!important}.viewtitle{font-size:22px!important}.briefing,.brief,.briefcard,[class*="briefing"]{min-height:0!important;padding:13px 15px!important;margin:8px 0 13px!important;background:linear-gradient(115deg,#0c2930,#0d1d2b)!important;border:1px solid #1d514f!important;border-radius:15px!important}.briefing h1,.briefing h2,.brief h1,.brief h2,[class*="briefing"] h1,[class*="briefing"] h2{font-size:clamp(19px,5vw,26px)!important;line-height:1.08!important;margin:2px 0 5px!important}.briefing p,.brief p,[class*="briefing"] p{margin:3px 0 7px!important;line-height:1.25!important;color:#a9c0c7!important}.briefing button,.brief button,[class*="briefing"] button{padding:7px 12px!important}
figure img,.hero img,.cover img,[class*="image"] img,.card img,.article img,.item img,.thumb img{width:100%;height:auto;max-height:46vh;object-fit:cover!important;object-position:center!important;border-radius:11px!important;background:#10212d}
#k-v37-bottom{position:fixed;z-index:99990;left:0;right:0;bottom:0;height:58px;padding:4px 8px max(4px,env(safe-area-inset-bottom));display:flex;justify-content:space-around;align-items:center;background:rgba(7,18,31,.97);border-top:1px solid #1c3745;backdrop-filter:blur(16px)}#k-v37-bottom button{border:0;background:none;color:#8ea3ad;display:flex;flex-direction:column;align-items:center;gap:1px;min-width:65px;font-size:10px;padding:3px 5px}#k-v37-bottom button b{font-size:18px;line-height:20px;font-weight:500}#k-v37-bottom button.on{color:#31c6ad}
#k-v37-settings{position:fixed;inset:0;z-index:999999;background:rgba(1,8,14,.72);display:none;align-items:flex-end}#k-v37-settings.open{display:flex}#k-v37-sheet{width:100%;max-height:88vh;overflow:auto;background:#0b1927;color:#f2f7f8;border:1px solid #1d3a48;border-radius:22px 22px 0 0;padding:18px 18px calc(18px + env(safe-area-inset-bottom));box-shadow:0 -12px 40px #0008}#k-v37-sheet h2{margin:0 0 15px;font:700 23px/1.1 var(--f-head)}.kvtitle{font:600 11px var(--f-mono);letter-spacing:.08em;text-transform:uppercase;color:#31c6ad;margin:17px 0 4px}.kvrow{display:grid;grid-template-columns:1fr auto;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid #193441}.kvrow label{font-weight:600}.kvrow small{display:block;color:#8ea3ad;font-weight:400}.kvseg{display:flex;gap:4px}.kvseg button{border:1px solid #284856;background:#102331;color:#d8e6e9;border-radius:9px;padding:6px 8px}.kvseg button.on{background:#31c6ad;color:#041411;border-color:#31c6ad}.kvtoggle{accent-color:#31c6ad;width:18px;height:18px}.kvclose{width:100%;margin-top:16px;border:0;border-radius:11px;padding:10px;background:#31c6ad;color:#041411;font-weight:700}
@media(max-width:760px){.layout{display:block!important;padding:10px 12px 28px!important}nav.sources{position:static!important;display:flex!important;overflow-x:auto!important;border:0!important;background:transparent!important;padding:4px 0 10px!important;gap:6px!important}.navlabel{display:none!important}.src{flex:none!important;border:1px solid #1d3a48!important;background:#0d1b2a!important;padding:6px 9px!important}.src .klogo{width:22px;height:22px}.brand{font-size:21px!important}.tools .btn{padding:6px 8px!important}.grid{grid-template-columns:1fr!important}.article{padding:14px!important}}
</style>'''
js=r'''<script id="v37-validated-js">
(()=>{const R=document.documentElement,LS=localStorage;R.dataset.theme='dark';
const apply=()=>{R.style.setProperty('--k-text-scale',LS.kText||'1');R.style.setProperty('--k-menu-scale',LS.kMenu||'.86')};apply();
const map={'le monde':'lemonde.fr','les echos':'lesechos.fr','le figaro':'lefigaro.fr','franceinfo':'franceinfo.fr','france info':'franceinfo.fr','01net':'01net.com','zdnet':'zdnet.fr','la tribune':'latribune.fr','univers freebox':'universfreebox.com','light reading':'lightreading.com','clubic':'clubic.com','numerama':'numerama.com','bfm':'bfmtv.com','orange':'orange.com'};
function enhanceSources(){document.querySelectorAll('.src').forEach(b=>{if(b.querySelector('.klogo'))return;const m=(b.textContent||'').trim().toLowerCase();let host='';for(const k in map)if(m.includes(k)){host=map[k];break}if(host){const i=document.createElement('img');i.className='klogo';i.src=`https://www.google.com/s2/favicons?domain=${host}&sz=64`;i.alt='';i.loading='lazy';b.prepend(i)}})}
function fixImages(root=document){root.querySelectorAll('img').forEach(i=>{const alt=i.dataset.src||i.getAttribute('data-lazy-src')||i.getAttribute('data-original');if((!i.src||i.src.startsWith('data:'))&&alt)i.src=alt;i.loading='lazy';i.decoding='async';i.addEventListener('error',()=>{const ss=i.getAttribute('srcset');if(ss){const u=ss.split(',').pop().trim().split(/\s+/)[0];if(u&&i.src!==u)i.src=u}},{once:true})})}
function rejectConsent(root=document){const words=['tout rejeter','refuser tout','continuer sans accepter','reject all','refuse all','refuser et continuer'];root.querySelectorAll('button,a').forEach(e=>{const t=(e.textContent||'').trim().toLowerCase();if(words.some(w=>t===w||t.includes(w)))try{e.click()}catch(_){}})}
function sheet(){if(document.getElementById('k-v37-settings'))return;const d=document.createElement('div');d.id='k-v37-settings';d.innerHTML=`<div id="k-v37-sheet"><h2>Réglages</h2><div class="kvtitle">Affichage</div><div class="kvrow"><div><label>Taille du texte</label><small>Articles et contenus</small></div><div class="kvseg" data-k="kText"><button data-v=".9">Petit</button><button data-v="1">Normal</button><button data-v="1.12">Grand</button></div></div><div class="kvrow"><div><label>Densité des menus</label><small>Navigation et catégories</small></div><div class="kvseg" data-k="kMenu"><button data-v=".76">Compact</button><button data-v=".86">Normal</button><button data-v="1">Grand</button></div></div><div class="kvtitle">Contenu</div><div class="kvrow"><div><label>Bloquer les pages de consentement</label><small>Privilégie le refus des traceurs</small></div><input class="kvtoggle" type="checkbox" checked disabled></div><div class="kvrow"><div><label>Chargement des images</label><small>Images optimisées et différées</small></div><input class="kvtoggle" type="checkbox" checked disabled></div><div class="kvrow"><div><label>Lecture dans l’application</label><small>Ouvrir les articles dans Kiosque</small></div><input class="kvtoggle" type="checkbox" checked></div><div class="kvtitle">Ma veille</div><div class="kvrow"><div><label>Sujets suivis</label><small>Gérer vos thèmes de veille</small></div><span>›</span></div><div class="kvrow"><div><label>Journaux et sources</label><small>Choisir vos publications</small></div><span>›</span></div><div class="kvtitle">Données et confidentialité</div><div class="kvrow"><div><label>Cache</label><small>Les contenus temporaires restent locaux</small></div><span>›</span></div><button class="kvclose">Terminé</button></div>`;document.body.appendChild(d);d.addEventListener('click',e=>{const b=e.target.closest('[data-v]');if(b){const g=b.parentElement,k=g.dataset.k;LS[k]=b.dataset.v;g.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));apply()}if(e.target===d||e.target.closest('.kvclose'))d.classList.remove('open')});window.kiosqueDisplaySettings=()=>{d.classList.add('open');d.querySelectorAll('.kvseg').forEach(g=>g.querySelectorAll('button').forEach(b=>b.classList.toggle('on',b.dataset.v===(LS[g.dataset.k]||({kText:'1',kMenu:'.86'}[g.dataset.k])))))};}
function bottom(){if(document.getElementById('k-v37-bottom'))return;const n=document.createElement('nav');n.id='k-v37-bottom';n.setAttribute('aria-label','Navigation principale');n.innerHTML=`<button class="on" data-kgo="home"><b>⌂</b><span>Accueil</span></button><button data-kgo="watch"><b>☆</b><span>Mes suivis</span></button><button data-kgo="explore"><b>⌕</b><span>Explorer</span></button><button data-kgo="library"><b>▤</b><span>Bibliothèque</span></button>`;document.body.appendChild(n);n.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;n.querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));const k=b.dataset.kgo;if(k==='home'){document.querySelector('.brand')?.scrollIntoView({behavior:'smooth'});document.querySelector('.menubar button')?.click()}else if(k==='watch'){[...document.querySelectorAll('button')].find(x=>/suivi|veille|favori/i.test(x.textContent||''))?.click()}else if(k==='explore'){document.querySelector('.search')?.focus()}else if(k==='library'){document.querySelector('nav.sources')?.scrollIntoView({behavior:'smooth'})}})}
function addSettingsEntry(){const c=[...document.querySelectorAll('button,.btn,.round')];const e=c.find(x=>/réglage|paramètre|settings/i.test(x.textContent||x.getAttribute('aria-label')||x.title||''));if(e&&!e.dataset.kv37){e.dataset.kv37='1';e.addEventListener('click',ev=>{ev.preventDefault();setTimeout(()=>window.kiosqueDisplaySettings(),20)})}}
const run=()=>{enhanceSources();fixImages();rejectConsent();addSettingsEntry()};const obs=new MutationObserver(run);obs.observe(document.documentElement,{subtree:true,childList:true});document.addEventListener('DOMContentLoaded',()=>{sheet();bottom();run()});setTimeout(()=>{sheet();bottom();run()},500);
})();
</script>'''
# Replace an earlier V37 patch if present, otherwise inject.
import re
s=re.sub(r'<style id="v37-validated-ui">.*?</style>',css,s,flags=re.S) if 'id="v37-validated-ui"' in s else s.replace('</head>',css+'\n</head>')
s=re.sub(r'<script id="v37-validated-js">.*?</script>',js,s,flags=re.S) if 'id="v37-validated-js"' in s else s.replace('</body>',js+'\n</body>')
p.write_text(s,encoding='utf-8')
print('V37 full validated redesign applied')
